def solve(inputs: dict) -> float:
    s = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])

    # Iterate k times: s = (a * s + b) % m
    for _ in range(k):
        s = (a * s + b) % m

    return float(s)
